spec.rawSql:
SELECT JSONExtractString(Body, 'reason') AS Reason,
  if(JSONHas(Body, 'inventory'), JSONExtractInt(Body, 'inventory'), NULL) AS `Inventory`,
  if(JSONHas(Body, 'liveInventory'), JSONExtractInt(Body, 'liveInventory'), NULL) AS `Live inventory`,
  if(JSONHas(Body, 'pairInventory'), JSONExtractInt(Body, 'pairInventory'), NULL) AS `Matching pair`,
  if(JSONHas(Body, 'allocatedInventory'), JSONExtractInt(Body, 'allocatedInventory'), NULL) AS `Allocated`,
  count() AS `Logged decisions`
FROM logs.otel_logs_k8s
WHERE Timestamp >= $__fromTime AND Timestamp <= $__toTime
  AND Namespace = ${namespace:singlequote}
  AND ServiceName = 'vault-solver-uniswapx'
  AND JSONExtractString(Body, 'solver') = 'uniswapx-filler'
  AND JSONExtractString(Body, 'msg') = 'liquidlane quote declined'
GROUP BY Reason, Inventory, `Live inventory`, `Matching pair`, Allocated
ORDER BY `Logged decisions` DESC LIMIT 50
